window.VisualizationTools.d3=function(element,json,callback){var container=document.createElement('div');element.appendChild(container);loadScript('https://d3js.org/d3.v5.min.js').then(function(){container.innerHTML='<svg></svg>';var svg=container.childNodes[0];callback(element,svg)}).catch(function(error){console.error('Could not load D3:',error)})}
window.VisualizationTools.cytoscape=function(element,json,callback){loadScript('https://cdnjs.cloudflare.com/ajax/libs/cytoscape/3.2.16/cytoscape.min.js').then(function(){if(json.width)$(element).width(json.width);if(json.height)$(element).height(json.height);json.data.container=element;callback(element,cytoscape(json.data))}).catch(function(error){console.error('Could not load cytoscape:',error)})} 